-- Confirmed guest count for the 1,500,000 VND hotpot set.
UPDATE menu_catalog SET data=json_set(data,'$.templates',json((SELECT json_group_array(json(CASE WHEN json_extract(value,'$.menu') LIKE 'DPA_MENU_V2:%' AND CASE WHEN json_valid(substr(json_extract(value,'$.menu'),13)) THEN json_extract(substr(json_extract(value,'$.menu'),13),'$.set.pricePerTable')=1500000 AND instr(lower(json_extract(value,'$.name')),'lẩu')>0 ELSE 0 END THEN json_set(value,'$.name','Lẩu 8 người – 1,500,000đ','$.menu','DPA_MENU_V2:'||json_set(substr(json_extract(value,'$.menu'),13),'$.set.name','Lẩu 8 người – 1,500,000đ','$.set.people',8)) ELSE value END)) FROM json_each(data,'$.templates')))),version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='dpa-shared' AND EXISTS(SELECT 1 FROM json_each(data,'$.templates') WHERE json_extract(value,'$.menu') LIKE 'DPA_MENU_V2:%' AND CASE WHEN json_valid(substr(json_extract(value,'$.menu'),13)) THEN json_extract(substr(json_extract(value,'$.menu'),13),'$.set.pricePerTable')=1500000 AND instr(lower(json_extract(value,'$.name')),'lẩu')>0 ELSE 0 END);
